import{_ as e,c as a,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const h=JSON.parse('{"title":"39、【蹇】 艮下坎上","description":"周易口诀义 - 39、【蹇】 艮下坎上","frontmatter":{"title":"39、【蹇】 艮下坎上","description":"周易口诀义 - 39、【蹇】 艮下坎上"},"headers":[],"relativePath":"zh/classics/koujueyi/041.md","filePath":"zh/classics/koujueyi/041.md"}'),r={name:"zh/classics/koujueyi/041.md"};function i(o,p,_,c,n,l){return t(),a("div",null,[...p[0]||(p[0]=[s('<h1 id="_39、【蹇】-艮下坎上" tabindex="-1">39、【蹇】 艮下坎上 <a class="header-anchor" href="#_39、【蹇】-艮下坎上" aria-label="Permalink to “39、【蹇】 艮下坎上”">​</a></h1><p>彖曰：「蹇」，难也，险在前也。见险而能止，知矣哉！「蹇利西南」，往得中也；「不利东北」，其道穷也。「利见大人」，往有功也。当位「贞吉」，以正邦也。「蹇」之时用大矣哉！</p><p>象曰：山上有水，「蹇」。君子以反身修德。</p><p>初六：往蹇来誉。</p><p>象曰：「往蹇来誉」，宜待也。</p><p>六二：王臣蹇蹇，匪躬之故。</p><p>象曰：「王臣蹇蹇」，终无尤也。</p><p>九三：往蹇来反。</p><p>象曰：「往蹇来反」，内喜之也。</p><p>六四：往蹇来连。象曰：「往蹇来连」，当位实也。</p><p>九五：大蹇朋来。</p><p>象曰：「大蹇朋来」，以中节也。</p><p>上六：往蹇来硕，吉。利见大人。</p><p>象曰：「往蹇来硕」，志在内也。「利见大人」，以从贵也。</p><p>无（四库全书标明，摘录时缺豫、随、无妄、大壮、晋、睽、蹇、解、中孚八卦）</p>',15)])])}const u=e(r,[["render",i]]);export{h as __pageData,u as default};
